package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LedgerSessionTest {
 LedgerSession session;String subject="345678901234567890123";
 @Before public void setup()throws Exception{Context context=RuntimeEnvironment.getApplication();context.deleteDatabase(AccountScope.databaseFor(subject));session=new LedgerSession(context.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null),subject);}
 @After public void close(){if(session!=null)session.close();}
 static void transaction(SQLiteDatabase db,String kind,long amount,String person,String loan){ContentValues v=new ContentValues();v.put("uuid",UUID.randomUUID().toString());v.put("kind",kind);v.put("amount",amount);v.put("day","2026-11-11");v.put("account","Cash");v.put("dest","");v.put("category",kind.equals("lent")||kind.startsWith("repay_")?"Debt":"Food");v.put("note","");v.put("person",person);v.put("loan",loan);db.insertOrThrow("tx",null,v);}
 long count(SQLiteDatabase db){try(Cursor c=db.rawQuery("SELECT count(*) FROM tx",null)){c.moveToFirst();return c.getLong(0);}}
 @Test public void sessionEditCapturesPreferencesCatalogAndMoneyTogether()throws Exception{LedgerSession.Ticket ticket=session.ticket();session.edit(ticket,(db,c,s)->{c.seed(new String[]{"Food"},new String[]{"Cash"});s.put("palette","Rose");transaction(db,"income",10000,"","");});assertEquals(4,session.snapshot(ticket).records.size());}
 @Test public void validationFailureRollsBackMoneyCatalogPreferenceAndOutbox()throws Exception{LedgerSession.Ticket ticket=session.ticket();session.edit(ticket,(db,c,s)->{c.seed(new String[]{"Food"},new String[]{"Cash"});transaction(db,"income",10000,"","");});long before=session.snapshot(ticket).revision;try{session.edit(ticket,(db,c,s)->{s.put("palette","Rose");c.put(null,"person","Must roll back",16,"Rose");transaction(db,"repay_in",10000,"Must roll back",UUID.randomUUID().toString());});fail();}catch(IllegalArgumentException expected){}assertEquals(before,session.snapshot(ticket).revision);session.edit(ticket,(db,c,s)->{assertEquals(1,count(db));assertEquals("Dynamic",s.get("palette"));assertNull(c.find("person","Must roll back"));});}
 @Test public void invalidatedFormsAndOtherSessionTicketsCannotWrite()throws Exception{LedgerSession.Ticket old=session.ticket();session.invalidateForms();try{session.edit(old,(db,c,s)->fail());fail();}catch(IllegalStateException expected){}LedgerSession other=LedgerSession.local(RuntimeEnvironment.getApplication());try{try{session.edit(other.ticket(),(db,c,s)->fail());fail();}catch(IllegalStateException expected){}}finally{other.close();}session.close();try{session.ticket();fail();}catch(IllegalStateException expected){}}
 @Test public void localSessionMigratesOriginalSchemaWithoutUploading()throws Exception{Context context=RuntimeEnvironment.getApplication();context.deleteDatabase("pocket.db");SQLiteDatabase db=context.openOrCreateDatabase("pocket.db",0,null);db.execSQL("CREATE TABLE tx(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,amount INTEGER NOT NULL,day TEXT NOT NULL,account TEXT NOT NULL,dest TEXT NOT NULL,category TEXT NOT NULL,note TEXT NOT NULL)");db.execSQL("INSERT INTO tx(kind,amount,day,account,dest,category,note) VALUES('income',10000,'2026-11-11','Cash','','Food','')");db.close();LedgerSession local=LedgerSession.local(context);try{assertFalse(local.accountLedger());local.edit(local.ticket(),(ledger,c,s)->{assertEquals(1,count(ledger));try(Cursor row=ledger.rawQuery("SELECT uuid FROM tx",null)){assertTrue(row.moveToFirst());Identifiers.uuid(row.getString(0));}assertEquals(0,ledger.rawQuery("SELECT name FROM sqlite_master WHERE name='cloud_outbox'",null).getCount());});try{local.snapshot(local.ticket());fail();}catch(IllegalStateException expected){}}finally{local.close();}}
 @Test public void pendingResetBlocksEditsAndOldFormsBeforeAnyUpload()throws Exception{LedgerSession.Ticket before=session.ticket();session.edit(before,(db,c,s)->{c.seed(new String[]{"Food"},new String[]{"Cash"});transaction(db,"income",10000,"","");});session.beginCloudReset(before);try{session.edit(before,(db,c,s)->fail());fail();}catch(IllegalStateException expected){}try{session.edit(session.ticket(),(db,c,s)->fail());fail();}catch(IllegalStateException expected){}assertFalse(session.snapshot(session.ticket()).records.isEmpty());}

 @Test public void formCannotOverwriteBackgroundMergeThroughAnotherDatabaseHandle()throws Exception{LedgerSession.Ticket ticket=session.ticket();session.edit(ticket,(db,c,s)->{c.seed(new String[]{"Food"},new String[]{"Cash"});transaction(db,"income",10000,"","");});LedgerSession.FormTicket form=session.formTicket();Context context=RuntimeEnvironment.getApplication();SQLiteDatabase other=context.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);try{LedgerSyncStore background=new LedgerSyncStore(other,subject);SyncEngine.Snapshot prior=background.snapshot();Map<String,SyncModel.Record> records=new TreeMap<>(prior.records);SyncModel.Record tx=null;for(SyncModel.Record r:records.values())if(new org.json.JSONObject(r.payload).optString("type").equals("transaction"))tx=r;assertNotNull(tx);records.put(tx.id,tx.edit("background_device",new org.json.JSONObject(tx.payload).put("note","Background merged").toString(),false));assertTrue(background.commitMerge(prior.revision,records));try{session.editForm(form,(db,c,s)->fail());fail();}catch(IllegalStateException expected){}}finally{other.close();}}

}
